WITH OrdersByStore AS (SELECT store_id, ROUND(STDDEV(discount), 2) AS stddev_discount, ROUND((100 * SUM(CASE WHEN status = 'SHIPPED' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_shipped FROM orders GROUP BY store_id) SELECT s.id, s.store_name, s.opened_date, O.stddev_discount, O.pct_shipped FROM stores s INNER JOIN OrdersByStore O ON s.id = O.store_id WHERE O.stddev_discount > 58 ORDER BY s.id
